      if (rng() < 0.7) props.push({ kind: 'tree', x: t, y: road + ROAD_HALF + 22 });
      props.push({ kind: 'lamp', x: road - ROAD_HALF - 10, y: t + 150 });
      props.push({ kind: 'lamp', x: t + 150, y: road - ROAD_HALF - 10 });
